    s=open(p).read()
    s=s.replace('import { consumeRateLimit } from "@/lib/rate-limit";','import { consumeRateLimit, setOrgPlan } from "@/lib/rate-limit";')
    if 'organization-repository' not in s:
        s=s.replace('import { assertOrgScope } from "@/lib/tenant";','import { assertOrgScope } from "@/lib/tenant";\nimport * as orgRepo from "@/server/repositories/organization-repository";',1)
    s=re.sub(r'(\n(\s*)const verdict = await consumeRateLimit\(\s*input\.orgId)', r'\n\2setOrgPlan(input.orgId, await orgRepo.findEffectivePlan(input.orgId));\n\1', s)
    open(p,'w').write(s)
